using System.Collections.Immutable;
using XamlG.Roslyn;
namespace XamlG.Compiler;

/// <summary>Composable immutable language policy. Compiler hosts consume the same profile and passes.</summary>
public sealed record XamlFrameworkProfile
{
    public static XamlFrameworkProfile Portable { get; } = new();
    public string Name { get; init; } = "Portable";
    public XamlTypeSystemConfiguration TypeSystem { get; init; } = new();
    public XamlRuntimeConfiguration Runtime { get; init; } = new();
    public ImmutableArray<IXamlTypeBindingRule> TypeBindingRules { get; init; } = ImmutableArray<IXamlTypeBindingRule>.Empty;
    public ImmutableArray<IXamlBindingRule> BindingRules { get; init; } = ImmutableArray<IXamlBindingRule>.Empty;
    public ImmutableArray<IXamlObjectBindingRule> ObjectBindingRules { get; init; } = ImmutableArray<IXamlObjectBindingRule>.Empty;
    public ImmutableArray<IXamlMemberBindingRule> MemberBindingRules { get; init; } = ImmutableArray<IXamlMemberBindingRule>.Empty;
    public ImmutableArray<IXamlPropertyBindingRule> PropertyBindingRules { get; init; } = ImmutableArray<IXamlPropertyBindingRule>.Empty;
    public ImmutableArray<IXamlMarkupBindingRule> MarkupBindingRules { get; init; } = ImmutableArray<IXamlMarkupBindingRule>.Empty;
    public ImmutableArray<IXamlTextConversionRule> TextConversionRules { get; init; } = ImmutableArray<IXamlTextConversionRule>.Empty;
    public ImmutableArray<IXamlDocumentPass> Passes { get; init; } = ImmutableArray<IXamlDocumentPass>.Empty;
}

using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using XamlG.Roslyn;
namespace XamlG.Compiler;

internal static class RuntimeContractBinder
{
    public static BoundRuntimeConfiguration Bind(BindingContext context)
    {
        var services = ImmutableArray.CreateBuilder<BoundServiceContract>();
        foreach (var mapping in context.Profile.Runtime.Services)
        {
            var type = context.Types.Find(mapping.InterfaceMetadataName);
            if (type == null || type.TypeKind != TypeKind.Interface || !context.Types.IsAccessible(type))
            { context.Report("XG1100", $"Service contract '{mapping.InterfaceMetadataName}' must resolve to an accessible interface.", new(0, 0)); continue; }
            services.Add(new(mapping, type, mapping.NamespaceItemMetadataName == null ? null : context.Types.Find(mapping.NamespaceItemMetadataName)));
        }
        IMethodSymbol? Resolve(XamlMethodReference? reference, int parameters)
        {
            if (reference == null) return null;
            var methods = context.Types.Find(reference.TypeMetadataName)?.Members(reference.MethodName).OfType<IMethodSymbol>().Where(m => m.IsStatic && m.Parameters.Length == parameters && context.Types.IsAccessible(m)).ToArray() ?? Array.Empty<IMethodSymbol>();
            if (methods.Length == 1) return methods[0];
            context.Report("XG1101", $"Runtime method '{reference.TypeMetadataName}.{reference.MethodName}' is missing or ambiguous.", new(0, 0)); return null;
        }
        return new(services.ToImmutable(), Resolve(context.Profile.Runtime.InnerServiceProviderFactory, 1), Resolve(context.Profile.Runtime.DeferredContentCustomizer, 2), context.Types.NamespaceMappings, context.Types.Compilation.AssemblyName ?? string.Empty);
    }
}
